    store_profile = current_browser->profile();
  }
  DCHECK(store_profile);
   if (store)
     *store = store_profile->GetRequestContext()->GetCookieStore();
   if (store_id)
    *store_id = helpers::GetStoreIdFromProfile(store_profile);
   return true;
 }
