                          const char   *name,
                          const char   *rule)
{
  Filter *filter;
  GList *filters, *new_filters;

  filter = filter_new (rule);
  if (g_hash_table_lookup_extended (proxy->filters,
                                    name,
                                    NULL, (void **)&filters))
