        NOTREACHED() << "Unsupported audio bit depth in crossfade.";
    }
     algorithm_.EnqueueBuffer(new DataBuffer(audio_data.Pass(), kRawDataSize));
     bytes_enqueued_ += kRawDataSize;
   }
