  for (size_t i = 0; i < arraysize(loop_filter_.ref_deltas); ++i)
    loop_filter_.ref_deltas[i] = default_ref_deltas[i];
  memset(loop_filter_.mode_deltas, 0, sizeof(loop_filter_.mode_deltas));
}
