void omx_vdec::free_input_buffer_header()
{
    input_use_buffer = false;
 if (arbitrary_bytes) {
 if (m_inp_heap_ptr) {
            DEBUG_PRINT_LOW("Free input Heap Pointer");
            free (m_inp_heap_ptr);
            m_inp_heap_ptr = NULL;
